use gpui_foreign_parent::{EditorRegistry,no_thread_assertion};
use std::cell::RefCell;
struct Window { value: u32 }
fn main() {
    let registry=EditorRegistry::new(no_thread_assertion);
    let owner=RefCell::new(Some(Box::new(Window { value:11 })));
    let pointer={ let owner=owner.borrow(); (&raw const **owner.as_ref().unwrap()).cast::<()>() };
    // SAFETY: live Window of the correct type, retained until unregister below.
    unsafe { registry.register(1u64,pointer) };
    registry.with(&1,|window: &Window| {
        registry.unregister(&1);
        drop(owner.borrow_mut().take());
        std::hint::black_box(window.value);
    });
}

